 36	    _ask: (prompt: string) => Promise<string> = askQuestion,
 37	    _confirm: (prompt: string, defaultYes?: boolean) => Promise<boolean> = askYesNo,
 38	): Promise<string> {
 39	    const hint = defaultValue ? ` (${defaultValue})` : '';
 40	
 41	    while (true) {
 42	        const raw = await _ask(`${label}${hint}:`);
 43	        const input = raw.trim() === '' && defaultValue ? defaultValue : raw.trim();
