 51	        // matches what loadConfig() / getProjectsFolder() expect.
 52	        const resolved = path.isAbsolute(input)
 53	            ? input
 54	            : path.resolve(getToolRoot(), input);
 55	
 56	        if (fs.existsSync(resolved)) {
 57	            return resolved;
 58	        }
 59	
 60	        const create = await _confirm(`  Directory does not exist. Create it?`, true);
